#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    int fives = 0, tens = 0;
    bool ok = true;
    for (int i = 0; i < n; i++) {
        int b;
        cin >> b;
        if (!ok) continue;
        if (b == 5) fives++;
        else if (b == 10) { if (fives) { fives--; tens++; } else ok = false; }
        else if (tens && fives) { tens--; fives--; }
        else if (fives >= 3) fives -= 3;
        else ok = false;
    }
    cout << (ok ? "YES" : "NO") << "\n";
    return 0;
}

