#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<long long> gas(n), cost(n);
    for (auto& x : gas) cin >> x;
    for (auto& x : cost) cin >> x;
    long long total = 0, tank = 0;
    int start = 0;
    for (int i = 0; i < n; i++) {
        total += gas[i] - cost[i];
        tank += gas[i] - cost[i];
        if (tank < 0) { start = i + 1; tank = 0; }
    }
    cout << (total < 0 ? -1 : start) << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
vector<int> parent;
int freeSlot(int t) { while (parent[t] != t) { parent[t] = parent[parent[t]]; t = parent[t]; } return t; }
int main() {
    int n;
    cin >> n;
    vector<pair<long long, int>> jobs(n);  // (profit, deadline)
    int maxD = 0;
    for (auto& [p, d] : jobs) { cin >> d >> p; maxD = max(maxD, d); }
    sort(jobs.rbegin(), jobs.rend());
    parent.resize(maxD + 1);
    iota(parent.begin(), parent.end(), 0);
    long long total = 0;
    for (auto& [p, d] : jobs) {
        int slot = freeSlot(d);
        if (slot > 0) { total += p; parent[slot] = slot - 1; }
    }
    cout << total << "\n";
    return 0;
}

